//! Stencil-Stack GPU compositor.
//!
//! Layers draw into offscreen textures. [`Compositor::compose`] then flattens
//! them back to front, ping-ponging between two accumulation textures so every
//! blend mode can read what is already below it. Procedural [`Fill`] layers are
//! generated by shader and need no widgets at all.
//!
//! Colour is straight (non-premultiplied) `Rgba8Unorm`; blending follows the
//! W3C compositing formula and is checked against [`blend::composite`].

pub mod blend;

use blend::{mode_index, BlendMode};
use bytemuck::{Pod, Zeroable};

pub const FORMAT: wgpu::TextureFormat = wgpu::TextureFormat::Rgba8Unorm;

/// A device and queue, shared by the compositor and whatever renders layers.
pub struct Gpu {
    pub device: wgpu::Device,
    pub queue: wgpu::Queue,
}

impl Gpu {
    /// A device with no window, for tests and offscreen work. `None` if no
    /// adapter exists (a software Vulkan driver counts).
    pub fn headless() -> Option<Gpu> {
        let instance = wgpu::Instance::default();
        let adapter =
            pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
                .ok()?;
        let (device, queue) =
            pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default())).ok()?;
        Some(Gpu { device, queue })
    }
}

/// Generated layer content.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Fill {
    Solid([f32; 4]),
    /// Top colour to bottom colour.
    VGradient {
        top: [f32; 4],
        bottom: [f32; 4],
    },
    /// Round glow: `color` at `center` (0..1) fading out at `radius` (fraction of the height).
    Glow {
        color: [f32; 4],
        center: [f32; 2],
        radius: f32,
        softness: f32,
    },
    /// Brushed metal: a gradient with fine vertical grain.
    BrushedMetal {
        top: [f32; 4],
        bottom: [f32; 4],
        grain: f32,
        seed: u32,
    },
}

pub enum Source<'a> {
    /// A layer some other renderer already drew.
    Texture(&'a wgpu::TextureView),
    Fill(Fill),
}

pub struct Layer<'a> {
    pub source: Source<'a>,
    pub blend: BlendMode,
    pub opacity: f32,
}

#[repr(C)]
#[derive(Clone, Copy, Pod, Zeroable)]
struct CompositeUniform {
    mode: u32,
    opacity: f32,
    pad: [f32; 2],
}

#[repr(C)]
#[derive(Clone, Copy, Pod, Zeroable)]
struct FillUniform {
    kind: u32,
    seed: u32,
    width: f32,
    height: f32,
    a: [f32; 4],
    b: [f32; 4],
    shape: [f32; 4],
}

impl Fill {
    fn uniform(&self, w: u32, h: u32) -> FillUniform {
        let base = FillUniform {
            kind: 0,
            seed: 0,
            width: w as f32,
            height: h as f32,
            a: [0.0; 4],
            b: [0.0; 4],
            shape: [0.0; 4],
        };
        match *self {
            Fill::Solid(c) => FillUniform {
                kind: 0,
                a: c,
                ..base
            },
            Fill::VGradient { top, bottom } => FillUniform {
                kind: 1,
                a: top,
                b: bottom,
                ..base
            },
            Fill::Glow {
                color,
                center,
                radius,
                softness,
            } => FillUniform {
                kind: 2,
                a: color,
                shape: [center[0], center[1], radius, softness],
                ..base
            },
            Fill::BrushedMetal {
                top,
                bottom,
                grain,
                seed,
            } => FillUniform {
                kind: 3,
                seed,
                a: top,
                b: bottom,
                shape: [grain, 0.0, 0.0, 0.0],
                ..base
            },
        }
    }
}

pub struct Compositor {
    composite: wgpu::RenderPipeline,
    composite_bgl: wgpu::BindGroupLayout,
    fill: wgpu::RenderPipeline,
    fill_bgl: wgpu::BindGroupLayout,
}

fn uniform_entry(binding: u32) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::FRAGMENT,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Uniform,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

fn texture_entry(binding: u32) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::FRAGMENT,
        ty: wgpu::BindingType::Texture {
            sample_type: wgpu::TextureSampleType::Float { filterable: false },
            view_dimension: wgpu::TextureViewDimension::D2,
            multisampled: false,
        },
        count: None,
    }
}

fn pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    bgl: &wgpu::BindGroupLayout,
) -> wgpu::RenderPipeline {
    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some(label),
        source: wgpu::ShaderSource::Wgsl(src.into()),
    });
    let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some(label),
        bind_group_layouts: &[Some(bgl)],
        immediate_size: 0,
    });
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(&layout),
        vertex: wgpu::VertexState {
            module: &module,
            entry_point: Some("vs_main"),
            buffers: &[],
            compilation_options: Default::default(),
        },
        primitive: wgpu::PrimitiveState::default(),
        depth_stencil: None,
        multisample: wgpu::MultisampleState::default(),
        fragment: Some(wgpu::FragmentState {
            module: &module,
            entry_point: Some("fs_main"),
            // No hardware blending: the shader does all of it.
            targets: &[Some(wgpu::ColorTargetState {
                format: FORMAT,
                blend: None,
                write_mask: wgpu::ColorWrites::ALL,
            })],
            compilation_options: Default::default(),
        }),
        multiview_mask: None,
        cache: None,
    })
}

/// A texture a layer can be rendered into and later composited.
pub fn layer_texture(device: &wgpu::Device, w: u32, h: u32, label: &str) -> wgpu::Texture {
    device.create_texture(&wgpu::TextureDescriptor {
        label: Some(label),
        size: wgpu::Extent3d {
            width: w.max(1),
            height: h.max(1),
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: FORMAT,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT
            | wgpu::TextureUsages::TEXTURE_BINDING
            | wgpu::TextureUsages::COPY_SRC,
        view_formats: &[],
    })
}

impl Compositor {
    pub fn new(device: &wgpu::Device) -> Self {
        let composite_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("stencil composite"),
            entries: &[uniform_entry(0), texture_entry(1), texture_entry(2)],
        });
        let fill_bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("stencil fill"),
            entries: &[uniform_entry(0)],
        });
        Self {
            composite: pipeline(
                device,
                "stencil composite",
                include_str!("composite.wgsl"),
                &composite_bgl,
            ),
            fill: pipeline(device, "stencil fill", include_str!("fill.wgsl"), &fill_bgl),
            composite_bgl,
            fill_bgl,
        }
    }

    fn uniform_buffer<T: Pod>(device: &wgpu::Device, data: &T) -> wgpu::Buffer {
        use wgpu::util::DeviceExt;
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("stencil uniform"),
            contents: bytemuck::bytes_of(data),
            usage: wgpu::BufferUsages::UNIFORM,
        })
    }

    fn pass<'a>(
        encoder: &'a mut wgpu::CommandEncoder,
        view: &'a wgpu::TextureView,
        clear: bool,
    ) -> wgpu::RenderPass<'a> {
        encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("stencil pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view,
                resolve_target: None,
                ops: wgpu::Operations {
                    load: if clear {
                        wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT)
                    } else {
                        wgpu::LoadOp::Load
                    },
                    store: wgpu::StoreOp::Store,
                },
                depth_slice: None,
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        })
    }

    /// Render a procedural fill into `target`.
    pub fn render_fill(&self, gpu: &Gpu, fill: &Fill, target: &wgpu::Texture) {
        let (w, h) = (target.width(), target.height());
        let ub = Self::uniform_buffer(&gpu.device, &fill.uniform(w, h));
        let bind = gpu.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("stencil fill"),
            layout: &self.fill_bgl,
            entries: &[wgpu::BindGroupEntry {
                binding: 0,
                resource: ub.as_entire_binding(),
            }],
        });
        let view = target.create_view(&Default::default());
        let mut enc = gpu.device.create_command_encoder(&Default::default());
        {
            let mut pass = Self::pass(&mut enc, &view, true);
            pass.set_pipeline(&self.fill);
            pass.set_bind_group(0, &bind, &[]);
            pass.draw(0..3, 0..1);
        }
        gpu.queue.submit([enc.finish()]);
    }

    /// Flatten `layers` (first = bottom) into a new `w`×`h` texture.
    pub fn compose(&self, gpu: &Gpu, w: u32, h: u32, layers: &[Layer<'_>]) -> wgpu::Texture {
        let mut acc = [
            layer_texture(&gpu.device, w, h, "stencil acc a"),
            layer_texture(&gpu.device, w, h, "stencil acc b"),
        ];
        let mut cur = 0usize;
        // Start from transparent.
        {
            let view = acc[cur].create_view(&Default::default());
            let mut enc = gpu.device.create_command_encoder(&Default::default());
            drop(Self::pass(&mut enc, &view, true));
            gpu.queue.submit([enc.finish()]);
        }
        for layer in layers {
            // Resolve the layer to a texture view; fills get a temporary target.
            let tmp;
            let src_view = match &layer.source {
                Source::Texture(v) => (*v).clone(),
                Source::Fill(f) => {
                    tmp = layer_texture(&gpu.device, w, h, "stencil fill layer");
                    self.render_fill(gpu, f, &tmp);
                    tmp.create_view(&Default::default())
                }
            };
            let dst_view = acc[cur].create_view(&Default::default());
            let out_view = acc[1 - cur].create_view(&Default::default());
            let ub = Self::uniform_buffer(
                &gpu.device,
                &CompositeUniform {
                    mode: mode_index(layer.blend),
                    opacity: layer.opacity,
                    pad: [0.0; 2],
                },
            );
            let bind = gpu.device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("stencil composite"),
                layout: &self.composite_bgl,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: ub.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: wgpu::BindingResource::TextureView(&dst_view),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: wgpu::BindingResource::TextureView(&src_view),
                    },
                ],
            });
            let mut enc = gpu.device.create_command_encoder(&Default::default());
            {
                let mut pass = Self::pass(&mut enc, &out_view, true);
                pass.set_pipeline(&self.composite);
                pass.set_bind_group(0, &bind, &[]);
                pass.draw(0..3, 0..1);
            }
            gpu.queue.submit([enc.finish()]);
            cur = 1 - cur;
        }
        acc.swap(0, cur);
        let [result, _] = acc;
        result
    }
}

/// Read a texture back as straight RGBA bytes (row-major, no padding).
pub fn read_rgba8(gpu: &Gpu, tex: &wgpu::Texture) -> Vec<[u8; 4]> {
    let (w, h) = (tex.width() as usize, tex.height() as usize);
    let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT as usize;
    let padded = (w * 4).div_ceil(align) * align;
    let buf = gpu.device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("stencil readback"),
        size: (padded * h) as u64,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let mut enc = gpu.device.create_command_encoder(&Default::default());
    enc.copy_texture_to_buffer(
        tex.as_image_copy(),
        wgpu::TexelCopyBufferInfo {
            buffer: &buf,
            layout: wgpu::TexelCopyBufferLayout {
                offset: 0,
                bytes_per_row: Some(padded as u32),
                rows_per_image: None,
            },
        },
        wgpu::Extent3d {
            width: w as u32,
            height: h as u32,
            depth_or_array_layers: 1,
        },
    );
    let idx = gpu.queue.submit([enc.finish()]);
    let slice = buf.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| drop(tx.send(r)));
    gpu.device
        .poll(wgpu::PollType::Wait {
            submission_index: Some(idx),
            timeout: None,
        })
        .expect("poll");
    rx.recv().expect("map").expect("map ok");
    let data = slice.get_mapped_range().expect("range");
    let mut out = Vec::with_capacity(w * h);
    for row in data.chunks_exact(padded).take(h) {
        out.extend(
            row[..w * 4]
                .chunks_exact(4)
                .map(|p| [p[0], p[1], p[2], p[3]]),
        );
    }
    out
}
